// @system @ref LLP 0420 §9 — wiring the platform text-geometry backend into
// `@exact/graphics`.
//
// `@exact/graphics` is framework-free and must not know how a platform finds
// its text metrics, so it takes an INJECTED `SyncTextGeometryBackend`. This
// module is the injection point, and it is the renderer's job because the
// renderer is the layer that already depends on both `@exact/text` and
// `@exact/graphics`.
//
// NO NEW SYNCHRONOUS MODULE SURFACE (LLP 0297 §6). Apple metrics come from
// `@exact/text`'s Apple backend, which reaches the host through the two
// already-registered `__hostCall` operations `text.measureParagraph` and
// `text.layoutParagraph`. Web metrics come from the pretext backend, which is
// canvas `measureText`. Neither operation set is widened here.
//
// Both backends load through a DYNAMIC import, and neither platform's module
// is ever FETCHED by the other platform. A bundler cannot see
// `globalThis.__exactPlatform`, so it EMITS both as split chunks — a web
// build carries an `apple-backend` chunk no browser ever requests, because
// `isApplePlatform()` runs before the `import()`. Say "fetched", not
// "bundled": a review of LLP 0420 read that chunk in a web asset list as an
// Apple backend shipping to browsers. The import starts at the first surface
// mount, well before the first scene build; until it resolves,
// `measureGraphicsText` uses its documented advance estimate and reports once.
//
// THE DYNAMIC IMPORTS BELOW DO NOT KEEP THIS MODULE OFF A NATIVE STARTUP
// GRAPH — they never did. The native startup-artifact walker links LITERAL
// `import()` edges into the served module table, so an earlier version of this
// header ("a Contract app with no graphics surface never pays for either") was
// measurably false: this module, both backends, and the five
// `@chenglou/pretext` modules behind the web one were all in the LLP 0413 blog
// lane's first-frame graph. What actually keeps them out is that this module is
// itself reached through `graphics-lazy.ts`, whose native variant uses an
// opaque specifier the walker cannot link (LLP 0128 `startup-budget`).

import {
  getGraphicsTextGeometryBackend,
  setGraphicsTextGeometryBackend,
} from '@exact/graphics/text';
import type { SyncTextGeometryBackend } from '@exact/text/geometry-api';

let loading = false;

/**
 * Whether the native sync bridge exists at all — a `typeof` probe and nothing
 * more.
 *
 * This module deliberately does NOT capture or forward `__hostCall`. The Apple
 * text backend already owns that resolution: it is the sync-by-design surface
 * LLP 0297 W3 decided on and the allowlisted one, and
 * `createAppleTextGeometryBackend()` falls back to its own bridge lookup when
 * no `hostCall` is passed. Reaching for the bridge here only to hand it
 * straight back added a second raw reference to the sync bridge for no gain,
 * which is what `sync-host-call-allowlist` exists to stop (LLP 0297 W4b,
 * ENG-22841).
 */
function hasNativeHostCallBridge(): boolean {
  return typeof (globalThis as { __hostCall?: unknown }).__hostCall === 'function';
}

function isApplePlatform(): boolean {
  const platform = (globalThis as { __exactPlatform?: unknown }).__exactPlatform;
  if (typeof platform !== 'string') return false;
  const normalized = platform.toLowerCase();
  return normalized === 'ios' || normalized === 'mac' || normalized === 'macos';
}

function install(backend: SyncTextGeometryBackend): void {
  if (getGraphicsTextGeometryBackend() === null) {
    setGraphicsTextGeometryBackend(backend);
  }
}

/**
 * Install the platform scene-text geometry backend. Idempotent, so every
 * surface mount can call it; the first call starts the load and later calls
 * are a map lookup.
 */
export function ensureGraphicsSceneTextGeometry(): void {
  if (loading || getGraphicsTextGeometryBackend() !== null) {
    return;
  }
  loading = true;

  const apple = isApplePlatform() && hasNativeHostCallBridge();
  const load: Promise<void> = apple
    ? import('@exact/text/native/apple-backend').then((module) => {
        install(module.createAppleTextGeometryBackend());
      })
    : import('@exact/text/web/pretext-backend').then((module) => {
        install(module.createPretextTextGeometryBackend());
      });

  void load.catch(() => {
    // A host whose text operations are not registered (or a bundle without
    // the backend chunk): @exact/graphics reports the missing backend once
    // and falls back to its advance estimate. Allow a later retry.
    loading = false;
  });
}

/** @internal test seam: forget the installed backend and allow a reload. */
export function resetGraphicsSceneTextGeometryForTests(): void {
  setGraphicsTextGeometryBackend(null);
  loading = false;
}
