// @system @ref LLP 0420 §9 — scene text measurement and tail ellipsis.
//
// WHY THIS FILE EXISTS. A scene `text` node may declare `maxWidth` and
// `ellipsize`; honoring them needs a *width* before a glyph is placed, which
// is inherently synchronous. LLP 0297 §6 forbids introducing a new
// synchronous module-call surface, so this module introduces none: it takes
// an INJECTED `SyncTextGeometryBackend` (`@exact/text`'s existing API — canvas
// `measureText` on web, the already-registered `text.measureParagraph` /
// `text.layoutParagraph` `__hostCall` operations on Apple) and adds no
// operation of its own. The injection also keeps `@exact/graphics`
// framework-free: nothing here imports a renderer, a DOM, or a host.
//
// WHO CALLS WHAT.
//   - The Contract runtime calls `setGraphicsTextGeometryBackend` once at
//     surface-mount time with the platform backend.
//   - Applications call `measureGraphicsText` / `fitGraphicsText` so the
//     ellipsis they compute is the ellipsis a backend would compute.
//   - The web canvas2d painter calls `fitGraphicsTextWithMeasure` with its
//     own `ctx.measureText`, so the painter and the app share ONE algorithm
//     rather than two implementations that agree by inspection.
//
// The Apple painter deliberately does NOT share this code: it truncates with
// `CTLineCreateTruncatedLine`, which is the platform's own truncation, so the
// ellipsis glyph, its font fallback, and the break point match the rest of
// the app's text. The two are held together by the §9 width-parity fixture
// (`tests/graphics/text-parity/`), not by a shared implementation.

import type { SyncTextGeometryBackend } from '@exact/text/geometry-api';

/** The v1 `ellipsize` value set (LLP 0420 §9). */
export const GRAPHICS_ELLIPSIZE_VALUES = ['none', 'clip', 'tail'] as const;
export type GraphicsEllipsize = (typeof GRAPHICS_ELLIPSIZE_VALUES)[number];

/** The single-character ellipsis the web/portable path appends. */
export const GRAPHICS_ELLIPSIS = '…';

/**
 * Advance-width estimate used when no geometry backend is installed (SSR, a
 * unit test, a host before its backend registers). 0.55em is the usual Latin
 * average advance — close enough to keep a layout from collapsing, never
 * close enough to claim parity, which is why it reports once.
 */
export const GRAPHICS_TEXT_ESTIMATE_EM = 0.55;

/** Default `fontSize` when a scene `text` node omits it (canvas2d default). */
export const GRAPHICS_TEXT_DEFAULT_FONT_SIZE = 12;

/** Default `fontFamily` when a scene `text` node omits it. */
export const GRAPHICS_TEXT_DEFAULT_FONT_FAMILY = 'sans-serif';

/** The font attrs a scene `text`/`batch` node carries. */
export interface GraphicsTextStyle {
  readonly fontFamily?: string;
  readonly fontSize?: number;
  readonly fontWeight?: number | string;
}

export interface GraphicsTextFitOptions {
  /** Layout width in scene units; absent/`Infinity` means unconstrained. */
  readonly maxWidth?: number;
  /** Defaults to `'none'` — paint unconstrained. */
  readonly ellipsize?: GraphicsEllipsize;
}

export interface GraphicsTextFit {
  /** The string to paint. */
  readonly text: string;
  /** Measured advance width of {@link GraphicsTextFit.text}. */
  readonly width: number;
  /** True when characters were dropped from the input. */
  readonly didTruncate: boolean;
}

/** Synchronous width measurer over one already-resolved font. */
export type GraphicsMeasureText = (text: string) => number;

type GraphicsTextDiagnostic = (code: string, message: string) => void;

let installedBackend: SyncTextGeometryBackend | null = null;
let reportDiagnostic: GraphicsTextDiagnostic = (code, message) => {
  console.warn(`[graphics/text] ${message}`, { code });
};
const reportedCodes = new Set<string>();

function reportOnce(code: string, message: string): void {
  if (reportedCodes.has(code)) return;
  reportedCodes.add(code);
  reportDiagnostic(code, message);
}

/**
 * Install (or clear, with `null`) the platform text-geometry backend. The
 * Contract runtime calls this at surface-mount time; tests call it directly.
 */
export function setGraphicsTextGeometryBackend(
  backend: SyncTextGeometryBackend | null,
): void {
  installedBackend = backend;
  if (backend !== null) {
    // A late backend must not be shouted down by an early miss.
    reportedCodes.delete('graphics_text_geometry_backend_missing');
  }
}

export function getGraphicsTextGeometryBackend(): SyncTextGeometryBackend | null {
  return installedBackend;
}

/** Redirect this module's structured diagnostics (tests, host loggers). */
export function setGraphicsTextDiagnosticSink(sink: GraphicsTextDiagnostic | null): void {
  reportDiagnostic =
    sink ??
    ((code, message) => {
      console.warn(`[graphics/text] ${message}`, { code });
    });
  reportedCodes.clear();
}

function resolvedFontSize(style: GraphicsTextStyle | undefined): number {
  const size = style?.fontSize;
  return typeof size === 'number' && Number.isFinite(size) && size > 0
    ? size
    : GRAPHICS_TEXT_DEFAULT_FONT_SIZE;
}

function normalizedFontWeight(
  weight: number | string | undefined,
): number | undefined {
  if (typeof weight === 'number' && Number.isFinite(weight)) return weight;
  if (typeof weight !== 'string') return undefined;
  const parsed = Number(weight);
  if (Number.isFinite(parsed)) return parsed;
  switch (weight.toLowerCase()) {
    case 'bold':
      return 700;
    case 'bolder':
      return 800;
    case 'light':
    case 'lighter':
      return 300;
    default:
      return undefined;
  }
}

/**
 * Estimate used with no backend installed. Counts CODE POINTS, so an
 * astral character costs one advance rather than two.
 */
export function estimateGraphicsTextWidth(
  value: string,
  style?: GraphicsTextStyle,
): number {
  let codePoints = 0;
  for (const _character of value) codePoints += 1;
  return codePoints * resolvedFontSize(style) * GRAPHICS_TEXT_ESTIMATE_EM;
}

/**
 * Advance width of one single-line scene text run, in scene units.
 *
 * Delegates to the injected `SyncTextGeometryBackend` — no new synchronous
 * module-call surface appears (LLP 0297 §6 / LLP 0420 §9). With no backend
 * installed it falls back to {@link estimateGraphicsTextWidth} and reports
 * `graphics_text_geometry_backend_missing` once.
 */
export function measureGraphicsText(value: string, style?: GraphicsTextStyle): number {
  if (value.length === 0) return 0;
  const backend = installedBackend;
  if (backend === null) {
    reportOnce(
      'graphics_text_geometry_backend_missing',
      'no text-geometry backend is installed — scene text width falls back to a ' +
        `${GRAPHICS_TEXT_ESTIMATE_EM}em advance estimate (LLP 0420 §9)`,
    );
    return estimateGraphicsTextWidth(value, style);
  }

  const fontSize = resolvedFontSize(style);
  const fontWeight = normalizedFontWeight(style?.fontWeight);
  try {
    const prepared = backend.prepare({
      spans: [
        {
          type: 'text',
          text: value,
          style: {
            fontFamily: style?.fontFamily ?? GRAPHICS_TEXT_DEFAULT_FONT_FAMILY,
            fontSize,
            ...(fontWeight === undefined ? {} : { fontWeight }),
          },
        },
      ],
    });
    // A single-line run is measured against an effectively unbounded width;
    // the caller's own maxWidth is a TRUNCATION budget, not a wrap budget —
    // scene text is single-line in v1 (`paragraph` owns wrapping).
    return prepared.measure({ maxWidth: Number.MAX_SAFE_INTEGER }).width;
  } catch (error) {
    reportOnce(
      'graphics_text_measure_failed',
      `text-geometry backend threw while measuring scene text — falling back to the advance estimate: ${
        error instanceof Error ? error.message : String(error)
      }`,
    );
    return estimateGraphicsTextWidth(value, style);
  }
}

/** Returns a measurer bound to one style — the shape hot loops want. */
export function createGraphicsTextMeasurer(style?: GraphicsTextStyle): GraphicsMeasureText {
  return (text: string) => measureGraphicsText(text, style);
}

const segmenter: { segment(input: string): Iterable<{ segment: string }> } | null = (() => {
  const IntlWithSegmenter = Intl as typeof Intl & {
    Segmenter?: new (
      locale?: string,
      options?: { granularity?: 'grapheme' },
    ) => { segment(input: string): Iterable<{ segment: string }> };
  };
  if (typeof IntlWithSegmenter.Segmenter !== 'function') return null;
  try {
    return new IntlWithSegmenter.Segmenter(undefined, { granularity: 'grapheme' });
  } catch {
    return null;
  }
})();

/**
 * Grapheme clusters, so a truncation point can never split a surrogate pair
 * or a combining sequence (LLP 0420 §9 "snapped outward to grapheme
 * boundaries"). Falls back to code points where `Intl.Segmenter` is absent —
 * still never splitting a surrogate pair.
 */
export function graphicsTextGraphemes(value: string): readonly string[] {
  if (segmenter === null) return Array.from(value);
  const clusters: string[] = [];
  for (const { segment } of segmenter.segment(value)) clusters.push(segment);
  return clusters;
}

/**
 * Fit `value` into `options.maxWidth` under `options.ellipsize`, measuring
 * with the injected `measure`.
 *
 * Every degenerate case terminates WITHOUT entering the binary search:
 *   - `ellipsize` absent or `'none'`     → the input, unconstrained;
 *   - `maxWidth` absent or `+Infinity`   → the input, unconstrained;
 *   - `maxWidth <= 0`, `NaN`, `-Infinity`→ the empty string, 0 measure calls;
 *   - the whole string already fits      → the input, 1 measure call;
 *   - the first grapheme (plus the
 *     ellipsis, for `'tail'`) overflows  → the bare ellipsis if THAT fits,
 *                                          otherwise the empty string, in at
 *                                          most 3 measure calls.
 *
 * Otherwise a binary search over grapheme counts converges to the longest
 * prefix that fits, in O(log n) measure calls.
 */
export function fitGraphicsTextWithMeasure(
  value: string,
  measure: GraphicsMeasureText,
  options: GraphicsTextFitOptions,
): GraphicsTextFit {
  const mode = options.ellipsize ?? 'none';
  const maxWidth = options.maxWidth;

  if (mode === 'none' || maxWidth === undefined || maxWidth === Number.POSITIVE_INFINITY) {
    return { text: value, width: measure(value), didTruncate: false };
  }
  // NaN and -Infinity are treated as a zero budget rather than as "unbounded":
  // a broken number must not silently widen a layout.
  if (!(maxWidth > 0)) {
    return { text: '', width: 0, didTruncate: value.length > 0 };
  }
  if (value.length === 0) {
    return { text: value, width: 0, didTruncate: false };
  }

  const full = measure(value);
  if (full <= maxWidth) {
    return { text: value, width: full, didTruncate: false };
  }

  const graphemes = graphicsTextGraphemes(value);
  const suffix = mode === 'tail' ? GRAPHICS_ELLIPSIS : '';
  const candidate = (count: number): string => graphemes.slice(0, count).join('') + suffix;

  // Cheapest possible rejection: if not even one grapheme plus the indicator
  // fits, no search can help. This is the "first character already overflows"
  // case, and the binary search must never be entered for it.
  const shortest = candidate(1);
  const shortestWidth = measure(shortest);
  if (shortestWidth > maxWidth) {
    // The bare indicator still says "there is content here that did not fit",
    // and it is what `CTLineCreateTruncatedLine` produces for the same budget,
    // so the two backends agree at the boundary instead of diverging there.
    if (suffix === '') {
      return { text: '', width: 0, didTruncate: true };
    }
    const suffixWidth = measure(suffix);
    return suffixWidth <= maxWidth
      ? { text: suffix, width: suffixWidth, didTruncate: true }
      : { text: '', width: 0, didTruncate: true };
  }

  let low = 1;
  let high = graphemes.length - 1;
  let bestCount = 1;
  let bestWidth = shortestWidth;
  while (low <= high) {
    const mid = (low + high) >>> 1;
    const width = measure(candidate(mid));
    if (width <= maxWidth) {
      bestCount = mid;
      bestWidth = width;
      low = mid + 1;
    } else {
      high = mid - 1;
    }
  }
  return { text: candidate(bestCount), width: bestWidth, didTruncate: true };
}

/**
 * {@link fitGraphicsTextWithMeasure} against the installed geometry backend.
 * This is the entry an application uses so its ellipsis agrees with the one
 * the backend painter would compute for the same node.
 */
export function fitGraphicsText(
  value: string,
  style: GraphicsTextStyle | undefined,
  options: GraphicsTextFitOptions,
): GraphicsTextFit {
  return fitGraphicsTextWithMeasure(
    value,
    (text) => measureGraphicsText(text, style),
    options,
  );
}

/** Narrowing helper for prop bags coming off a scene node. */
export function graphicsEllipsizeValue(value: unknown): GraphicsEllipsize | undefined {
  return typeof value === 'string' &&
    (GRAPHICS_ELLIPSIZE_VALUES as readonly string[]).includes(value)
    ? (value as GraphicsEllipsize)
    : undefined;
}
